import{_ as i,a as n,c as a,ac as l}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第四册：流利英语 · 单元 3：证据、解释与表达焦点","description":"L17–L24 的学习目标、课时入口和复习方法。","frontmatter":{"title":"第四册：流利英语 · 单元 3：证据、解释与表达焦点","description":"L17–L24 的学习目标、课时入口和复习方法。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"L17–L24 的学习目标、课时入口和复习方法。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 单元 2 复习与自测","link":"/life/english/new-concept/book-4/unit-02/review"},"next":{"text":"第四册：流利英语 · 单元 3 语法总结","link":"/life/english/new-concept/book-4/unit-03/grammar"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 单元 2 复习与自测","link":"/life/english/new-concept/book-4/unit-02/review"},"next":{"text":"第四册：流利英语 · 单元 3 语法总结","link":"/life/english/new-concept/book-4/unit-03/grammar"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/overview.md","filePath":"life/english/new-concept/book-4/unit-03/overview.md"}'),t={name:"life/english/new-concept/book-4/unit-03/overview.md"};function o(s,e,r,c,h,d){return n(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="第四册-流利英语-·-单元-3-证据、解释与表达焦点" tabindex="-1">第四册：流利英语 · 单元 3：证据、解释与表达焦点 <a class="header-anchor" href="#第四册-流利英语-·-单元-3-证据、解释与表达焦点" aria-label="Permalink to &quot;第四册：流利英语 · 单元 3：证据、解释与表达焦点&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元导读</a> · <a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元复习与自测</a></p><h2 id="单元导读" tabindex="-1">单元导读 <a class="header-anchor" href="#单元导读" aria-label="Permalink to &quot;单元导读&quot;">​</a></h2><p>L17–L24。第17—24课涉及生态干预、动物观察、梦、物质分类、电影、知识、飞行与审美。每篇都要求识别证据类型：报告、观察、解释或个人评价。学习通过分词、同位语从句、强调句和倒装组织复杂信息，同时检查压缩是否丢掉逻辑主语或隐藏了未经证明的推断。阶段输出从描述事实逐步走向有依据的短评。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>区分相关关系和因果判断</li><li>辨认从句功能与逻辑主语</li><li>用具体证据支撑艺术或知识评论</li></ul><h2 id="课时目录" tabindex="-1">课时目录 <a class="header-anchor" href="#课时目录" aria-label="Permalink to &quot;课时目录&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-4/unit-03/lesson-017">Lesson 17 · A man-made disease</a></li><li><a href="/life/english/new-concept/book-4/unit-03/lesson-018">Lesson 18 · Porpoises</a></li><li><a href="/life/english/new-concept/book-4/unit-03/lesson-019">Lesson 19 · The stuff of dreams</a></li><li><a href="/life/english/new-concept/book-4/unit-03/lesson-020">Lesson 20 · Snake poison</a></li><li><a href="/life/english/new-concept/book-4/unit-03/lesson-021">Lesson 21 · William S. Hart and the early &#39;Western&#39; film</a></li><li><a href="/life/english/new-concept/book-4/unit-03/lesson-022">Lesson 22 · Knowledge and progress</a></li><li><a href="/life/english/new-concept/book-4/unit-03/lesson-023">Lesson 23 · Bird flight</a></li><li><a href="/life/english/new-concept/book-4/unit-03/lesson-024">Lesson 24 · Beauty</a></li></ul><h2 id="单元知识地图" tabindex="-1">单元知识地图 <a class="header-anchor" href="#单元知识地图" aria-label="Permalink to &quot;单元知识地图&quot;">​</a></h2><ul><li>L17：cause、lead to 与 be associated with。不要把 associated with 在摘要中升级为 caused；这改变了证据含义。</li><li>L18：感官动词的主动与被动转换。The animal was seen surface 缺少 to；主动 We saw it surface 才使用不带 to 结构。</li><li>L19：同位语从句与定语从句。不要把 belief 自动译成“事实”；the belief that 只标明某人持有的看法。</li><li>L20：过去分词作后置定语。不要把 collected 当成全句唯一谓语而漏掉 were analysed；该短语只限定样本。</li><li>L21：It is/was…that 强调句。It was in 1910 when… 若意在强调时间，应使用 that；when 另可引导关系或时间从句。</li><li>L22：what 从句作主语与表语。That matters is… 不能替代 What matters is…；what 在从句中还承担 matters 的主语。</li><li>L23：现在分词状语与逻辑主语。Watching the bird, its wings looked wide 错把 wings 当观察者；可改为 As I watched the bird, its wings looked wide。</li><li>L24：否定或限制副词前置倒装。Rarely two viewers notice… 缺倒装；Rarely do two viewers notices… 又错误地给实义动词加 s。</li></ul><h2 id="完成标准" tabindex="-1">完成标准 <a class="header-anchor" href="#完成标准" aria-label="Permalink to &quot;完成标准&quot;">​</a></h2><p>能用自己的例子说明上面的语法点；能在不看答案时完成单元自测；能完成至少一项口头表达和一项书面表达，并根据课时点评修订。若做错，不必整单元重学，沿题目链接回到相应课时。</p>',13)])])}const p=i(t,[["render",o]]);export{f as __pageData,p as default};
